toolScript:
// --- 1. BLACK-SCHOLES QUANT ENGINE ---
        const ND = (x) => Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
        const CND = (x) => {
            if (x < 0) return 1 - CND(-x);
            let k = 1 / (1 + 0.2316419 * x);
            return 1 - ND(x) * (0.319381530 * k - 0.356563782 * k * k + 1.781477937 * k * k * k - 1.821255978 * k * k * k * k + 1.330274429 * k * k * k * k * k);
        };
        let state = {
            spot: 100,
            iv: 0.30,
            type: 'call',
            greek: 'delta',
            r: 0.05
        };
        function syncIV(val) {
            state.iv = parseFloat(val) / 100;
            document.getElementById('in-iv').value = val;
            document.getElementById('in-iv-slider').value = val;
            // Interaction Hint
            if (val > 80) showHint("High IV expands the Risk Surface! ");
            else if (val < 20) showHint("Low IV compresses premiums. ");
            renderHeatmap();
        }
        function setType(type) {
            state.type = type;
            document.getElementById('btn-call').className = type === 'call' ? 'flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all bg-slate-900 text-white shadow-lg' : 'flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all text-slate-400 hover:text-slate-800';
            document.getElementById('btn-put').className = type === 'put' ? 'flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all bg-slate-900 text-white shadow-lg' : 'flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all text-slate-400 hover:text-slate-800';
            renderHeatmap();
        }
        function setGreek(greek) {
            state.greek = greek;
            document.querySelectorAll('.greek-btn').forEach(b => b.classList.remove('active'));
            document.getElementById(`btn-${greek}`).classList.add('active');
            const tips = {
                'delta': 'Delta estimates probability of expiring ITM.',
                'gamma': 'Gamma identifies explosive risk zones.',
                'theta': 'Theta shows daily cash burn rates.',
                'vega': 'Vega shows sensitivity to volatility shifts.'
            };
            document.getElementById('dynamic-tip').innerText = tips[greek];
            renderHeatmap();
        }
        function getColor(val, min, max, greek) {
            let ratio = (val - min) / (max - min);
            if (greek === 'theta') {
                ratio = 1 - ((val - min) / (max - min));
                const lightness = 95 - (ratio * 50);
                return `hsl(0, 80%, ${lightness}%)`;
            }
            if (greek === 'gamma') {
                const lightness = 95 - (ratio * 50);
                return `hsl(30, 90%, ${lightness}%)`;
            }
            const hue = state.type === 'call' ? 220 : 270;
            const lightness = 95 - (ratio * 50);
            return `hsl(${hue}, 80%, ${lightness}%)`;
        }
        function calculateBS(S, K, T, V, R, type) {
            if (T <= 0) return 0; // Expired
            const d1 = (Math.log(S / K) + (R + V * V / 2) * T) / (V * Math.sqrt(T));
            const d2 = d1 - V * Math.sqrt(T);
            // Return calculated Greek
            if (state.greek === 'delta') return type === 'call' ? CND(d1) : CND(d1) - 1;
            if (state.greek === 'gamma') return ND(d1) / (S * V * Math.sqrt(T));
            if (state.greek === 'vega') return S * ND(d1) * Math.sqrt(T) / 100;
            if (state.greek === 'theta') {
                let t = (- (S * ND(d1) * V) / (2 * Math.sqrt(T)));
                if (type === 'call') t -= R * K * Math.exp(-R * T) * CND(d2);
                else t += R * K * Math.exp(-R * T) * CND(-d2);
                return t / 365;
            }
            // Return Price for simulator
            if (state.greek === 'price') {
                if (type === 'call') return S * CND(d1) - K * Math.exp(-R * T) * CND(d2);
                else return K * Math.exp(-R * T) * CND(-d2) - S * CND(-d1);
            }
            return 0;
        }
        // Return Option Price helper
        function getOptionPrice(S, K, T, V, R, type) {
            const d1 = (Math.log(S / K) + (R + V * V / 2) * T) / (V * Math.sqrt(T));
            const d2 = d1 - V * Math.sqrt(T);
            if (type === 'call') return S * CND(d1) - K * Math.exp(-R * T) * CND(d2);
            else return K * Math.exp(-R * T) * CND(-d2) - S * CND(-d1);
        }
        function renderHeatmap() {
            state.spot = parseFloat(document.getElementById('in-spot').value);
            const grid = document.getElementById('heatmap-grid');
            grid.innerHTML = '';
            const strikes = [];
            for (let k = state.spot * 0.8; k <= state.spot * 1.2; k += state.spot * 0.05) strikes.push(Math.round(k));
            const expiries = [7, 14, 21, 30, 45, 60, 90, 120, 180];
            let minVal = Infinity, maxVal = -Infinity;
            const values = [];
            // First pass: Calculate min/max for color normalization
            expiries.forEach((dte, r) => {
                values[r] = [];
                strikes.forEach((k, c) => {
                    const val = calculateBS(state.spot, k, dte / 365, state.iv, state.r, state.type);
                    values[r][c] = val;
                    if (val < minVal) minVal = val;
                    if (val > maxVal) maxVal = val;
                });
            });
            if (state.greek === 'gamma' || state.greek === 'vega') minVal = 0;
            grid.style.display = 'grid';
            grid.style.gridTemplateColumns = `50px repeat(${strikes.length}, 1fr)`;
            // Header Row (Strikes)
            const empty = document.createElement('div');
            empty.className = 'heatmap-header border-r border-b border-slate-200 flex items-center justify-center font-mono';
            empty.innerText = 'DTE';
            grid.appendChild(empty);
            strikes.forEach(k => {
                const el = document.createElement('div');
                el.className = 'heatmap-header border-b border-slate-200 flex items-center justify-center';
                el.innerText = '$' + k;
                grid.appendChild(el);
            });
            // Grid Rows
            expiries.forEach((dte, r) => {
                const label = document.createElement('div');
                label.className = 'heatmap-header border-r border-slate-200 flex items-center justify-center font-mono';
                label.innerText = dte + 'd';
                grid.appendChild(label);
                strikes.forEach((k, c) => {
                    const val = values[r][c];
                    const cell = document.createElement('div');
                    // Stagger animation based on index
                    cell.className = 'heatmap-cell opacity-0';
                    cell.style.animationDelay = `${(r * 5 + c) * 10}ms`;
                    cell.classList.add('animate-in');
                    cell.style.backgroundColor = getColor(val, minVal, maxVal, state.greek);
                    cell.innerText = val.toFixed(3);
                    // Interaction Logic
                    cell.onclick = () => openSimulator(k, dte, val);
                    grid.appendChild(cell);
                });
            });
        }
        // --- 2. DOPAMINE / SIMULATOR LOGIC ---
        function openSimulator(strike, dte, currentGreek) {
            const modal = document.getElementById('sim-modal');
            const content = document.getElementById('sim-content');
            modal.style.display = 'flex';
            const price = getOptionPrice(state.spot, strike, dte / 365, state.iv, state.r, state.type).toFixed(2);
            const contractCost = price * 100;
            content.innerHTML = `
                <div class="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-4">
                    <div class="flex justify-between items-center mb-2">
                        <span class="text-xs font-bold text-slate-500 uppercase">Selected Contract</span>
                        <span class="text-xs font-black text-slate-900 bg-white px-2 py-1 rounded shadow-sm border border-slate-100">${state.type.toUpperCase()} ${strike} @ ${dte}d</span>
                    </div>
                    <div class="grid grid-cols-2 gap-4 mt-4">
                        <div class="text-center">
                            <div class="text-[10px] text-slate-400 uppercase font-bold tracking-wider">Theoret. Value</div>
                            <div class="text-2xl font-black text-slate-800">$${price}</div>
                        </div>
                        <div class="text-center">
                            <div class="text-[10px] text-slate-400 uppercase font-bold tracking-wider">Current ${state.greek}</div>
                            <div class="text-2xl font-black text-${state.greek === 'theta' ? 'rose' : 'blue'}-600">${currentGreek.toFixed(3)}</div>
                        </div>
                    </div>
                </div>
                <div class="text-xs text-slate-500 text-center font-medium italic">
                    If Spot moves +$5.00 tomorrow, this option gains approximately <span class="font-bold text-emerald-600">$${(calculateBS(state.spot, strike, dte / 365, state.iv, state.r, state.type) * 5 * 100).toFixed(0)}</span> in value (excluding decay).
                </div>
            `;
        }
        function closeModal() {
            document.getElementById('sim-modal').style.display = 'none';
        }
        // --- 3. ONBOARDING TOUR LOGIC ---
        const tourSteps = [
            {
                elementId: 'app-header', // Fallback anchor
                text: "Welcome to the Matrix. This tool visualizes the 'Risk Surface' of options using the Nobel Prize-winning Black-Scholes model. Let's get you oriented.",
                position: 'center'
            },
            {
                elementId: 'controls-area',
                text: "Step 1: The Inputs. Enter the stock price and adjust Implied Volatility (IV). Watch how the entire grid reacts instantly.",
                position: 'bottom'
            },
            {
                elementId: 'greek-selector',
                text: "Step 2: Choose your Risk. Switch between Delta (Direction), Theta (Time Decay), and Gamma (Acceleration) to see different dimensions of risk.",
                position: 'bottom'
            },
            {
                elementId: 'heatmap-container-wrapper',
                text: "Step 3: The Surface. X-Axis is Price, Y-Axis is Time. Darker colors indicate higher sensitivity. Click any cell to run a P&L Scenario.",
                position: 'top'
            }
        ];
        let currentTourStep = 0;
        function startTour() {
            if (window.innerWidth < 768) {
                alert("Please rotate your device or use a desktop for the guided tour.");
                return;
            }
            currentTourStep = 0;
            document.getElementById('tour-layer').classList.remove('hidden');
            renderTourStep();
        }
        function renderTourStep() {
            const layer = document.getElementById('tour-layer');
            const step = tourSteps[currentTourStep];
            const target = document.getElementById(step.elementId) || document.body;
            const rect = target.getBoundingClientRect();
            // Create Mask
            layer.innerHTML = `
                <div class="absolute inset-0 bg-slate-900/60 transition-all duration-500">
                    <div class="tour-highlight absolute transition-all duration-300 bg-transparent border-2 border-white/50" 
                         style="top: ${rect.top - 10}px; left: ${rect.left - 10}px; width: ${rect.width + 20}px; height: ${rect.height + 20}px;">
                    </div>
                    <div class="tour-tooltip" style="top: ${rect.bottom + 20}px; left: ${Math.max(20, rect.left)}px;">
                        <div class="flex justify-between items-center mb-3">
                            <span class="text-[10px] font-black uppercase tracking-widest text-slate-400">Step ${currentTourStep + 1}/${tourSteps.length}</span>
                            <button onclick="endTour()" class="text-slate-400 hover:text-slate-800 text-xs"><svg class="w-4 h-4 inline-block text-rose-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
                        </div>
                        <p class="text-sm font-medium text-slate-700 leading-relaxed mb-4">${step.text}</p>
                        <div class="flex justify-end gap-2">
                            ${currentTourStep > 0 ? `<button onclick="prevStep()" class="px-3 py-1.5 text-xs font-bold text-slate-500 hover:text-slate-800">Back</button>` : ''}
                            <button onclick="nextStep()" class="px-4 py-2 bg-[#EE6C4D] text-white text-xs font-bold rounded-lg shadow-lg hover:bg-[#d75a3c] transition">
                                ${currentTourStep === tourSteps.length - 1 ? 'Finish' : 'Next'}
                            </button>
                        </div>
                    </div>
                </div>
            `;
        }
        function nextStep() {
            if (currentTourStep < tourSteps.length - 1) {
                currentTourStep++;
                renderTourStep();
            } else {
                endTour();
            }
        }
        function prevStep() {
            if (currentTourStep > 0) {
                currentTourStep--;
                renderTourStep();
            }
        }
        function endTour() {
            document.getElementById('tour-layer').classList.add('hidden');
            // Check local storage so we don't show it every time (optional)
            localStorage.setItem('quant-tour-completed', 'true');
        }
        // --- 4. HINT SYSTEM ---
        function showHint(msg) {
            const bubble = document.getElementById('hint-bubble');
            bubble.innerText = " " + msg;
            bubble.classList.remove('opacity-0');
            setTimeout(() => bubble.classList.add('opacity-0'), 4000);
        }
        // --- 5. INITIALIZATION ---
        document.addEventListener('DOMContentLoaded', () => {
            renderHeatmap();
            // Auto-start tour if first visit
            if (!localStorage.getItem('quant-tour-completed')) {
                setTimeout(startTour, 1000);
            }
        });
